#3. Logical Operators:

print("Logical Operators:")
print("True and True = ", True and True) # Logical AND (will return True if both the operands are True, otherwise it will return False)
print("True and False = ", True and False) # Logical AND (will return True if both the operands are True, otherwise it will return False)
print("False and True = ", False and True) # Logical AND (will return True if both the operands are True, otherwise it will return False)
print("False and False = ", False and False) # Logical AND (will return True if both the operands are True, otherwise it will return False)
print("True or True = ", True or True) # Logical OR (will return True if at least one of the operands is True, otherwise it will return False)
print("True or False = ", True or False) # Logical OR (will return True if at least one of the operands is True, otherwise it will return False)
print("False or True = ", False or True) # Logical OR (will return True if at least one of the operands is True, otherwise it will return False)
print("False or False = ", False or False) # Logical OR (will return True if at least one of the operands is True, otherwise it will return False)
print("not True = ", not True) # Logical NOT (will return True if the operand is False, otherwise it will return False)
print("not False = ", not False) # Logical NOT (will return True if the operand is False, otherwise it will return False)
print("not (True and False) = ", not (True and False)) # Logical NOT (will return True if the operand is False, otherwise it will return False)